import{_ as e,b as t,c as r,I as o}from"./chunks/framework.C6cPs9Ia.js";const c=JSON.parse('{"title":"2026 夏季番扫雷报告","description":"2026 年夏季新番扫雷总结——一个高中生的追番台账与好感度排名","frontmatter":{"title":"2026 夏季番扫雷报告","date":"2026-09-06T00:00:00.000Z","tags":["动画","追番","扫雷"],"cover":"/LQY/images/cover-anime.webp","head":[["meta",{"name":"description","content":"2026 年夏季新番扫雷总结——一个高中生的追番台账与好感度排名"}],["meta",{"name":"keywords","content":"夏季番, 追番, 动画, 扫雷报告"}]]},"headers":[],"relativePath":"posts/anime-summer.md","filePath":"posts/anime-summer.md"}'),n={name:"posts/anime-summer.md"};function s(i,a,l,p,h,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<p>夏季番基本收官，来交作业。这个季度的扫雷原则是<strong>三集定生死</strong>，撑不过三集的直接弃疗（时间就是分数，分数就是零花钱）。</p><hr><h2 id="本季前三名" tabindex="-1">本季前三名 <a class="header-anchor" href="#本季前三名" aria-label="Permalink to &quot;本季前三名&quot;">​</a></h2><h3 id="🥇-第一名-音乐番黑马" tabindex="-1">🥇 第一名：音乐番黑马 <a class="header-anchor" href="#🥇-第一名-音乐番黑马" aria-label="Permalink to &quot;🥇 第一名：音乐番黑马&quot;">​</a></h3><p>毫无悬念的本季最佳。一支高中生乐队从零开始的故事，作画在演奏场景完全放飞，作监像是把预算全烧在了琴弦的振动上。</p><p>第八集的那首插入曲，我在深夜戴耳机循环到宿管敲门。看完当晚就打开购物软件搜了贝斯价格，然后看了看余额，默默关掉。（梦想：暂存购物车。）</p><p><strong>好感度：★★★★★</strong>（扣半星是因为每周等更新的感觉太煎熬）</p><h3 id="🥈-第二名-治愈系日常" tabindex="-1">🥈 第二名：治愈系日常 <a class="header-anchor" href="#🥈-第二名-治愈系日常" aria-label="Permalink to &quot;🥈 第二名：治愈系日常&quot;">​</a></h3><p>万物皆可治愈系的年代，这部能杀出来靠的是<strong>节奏</strong>。没有强行煽情，没有突然催泪，就是一群人认认真真地过日子。适合写完一张理综卷之后看一集回血。</p><p>看板娘 Shizuku 同款喜欢点：里面有一只戏份不少的猫。（是的，我个人的私心评测标准，怎么了。）</p><p><strong>好感度：★★★★☆</strong></p><h3 id="🥉-第三名-热血战斗系" tabindex="-1">🥉 第三名：热血战斗系 <a class="header-anchor" href="#🥉-第三名-热血战斗系" aria-label="Permalink to &quot;🥉 第三名：热血战斗系&quot;">​</a></h3><p>打斗分镜是本季天花板，但剧情推进稍微赶了点，原作党说&quot;魔改了前三卷&quot;。没看过原作的我表示：单看动画，爽就完了。</p><p><strong>好感度：★★★★☆</strong>（原著党建议绕行保平安）</p><h2 id="遗憾退场" tabindex="-1">遗憾退场 <a class="header-anchor" href="#遗憾退场" aria-label="Permalink to &quot;遗憾退场&quot;">​</a></h2><ul><li>某部宣发很猛的异世界番：三集看了个寂寞，男主的动机我到现在没搞懂。<strong>弃</strong>。</li><li>某部续作第二季：第一季封神，这季建模肉眼可见的赶工。忍到第四集，<strong>弃</strong>。旧的好印象要留着，不能自己亲手毁掉。</li></ul><h2 id="拔草区-下季度目标" tabindex="-1">拔草区（下季度目标） <a class="header-anchor" href="#拔草区-下季度目标" aria-label="Permalink to &quot;拔草区（下季度目标）&quot;">​</a></h2><p>秋季番表已经拉出来了，目前想追的有 4 部，其中 1 部是万众期待的续作。计划赶不上变化，具体看 10 月的月考安排——<strong>如果哪周没更新扫雷报告，那一定是我被函数打败了。</strong></p><hr><p>最后例行求安利：评论区留下你这个夏天的最佳，说得出理由的我必补。片荒的高中生，等投喂。喵。</p>',20)])])}const u=e(n,[["render",s]]);export{c as __pageData,u as default};
